#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Temperature { // Store as i16 to save memory (16-bit vs 32-bit f32) // Resolution: 0.1°C, Range: -3276.8°C to +3276.7°C // More than enough for ESP32-C3's typical -40°C to +125°C range celsius_tenths: i16,
} impl Temperature { /// Create temperature from Celsius value pub const fn from_celsius(celsius: f32) -> Self { Self { celsius_tenths: (celsius * 10.0) as i16, } } /// Create temperature from raw ESP32 sensor reading pub const fn from_sensor_raw(raw_value: u16) -> Self { // ESP32-C3 temperature sensor specific conversion // This is a simplified conversion - real implementation depends on calibration let celsius = (raw_value as f32 - 1000.0) / 10.0; Self::from_celsius(celsius) } /// Get temperature as Celsius f32 pub fn celsius(&self) -> f32 { self.celsius_tenths as f32 / 10.0 } /// Get temperature as Fahrenheit f32 pub fn fahrenheit(&self) -> f32 { self.celsius() * 9.0 / 5.0 + 32.0 } /// Check if temperature is within normal range pub const fn is_normal_range(&self) -> bool { // Normal room temperature: 15-35°C self.celsius_tenths >= 150 && self.celsius_tenths <= 350 } /// Check if temperature is too high (potential overheating) pub const fn is_overheating(&self) -> bool { self.celsius_tenths > 1000 // > 100°C }
} // Implement Display for serial output
