Let's add comprehensive tests to our embedded temperature code: // src/lib.rs - Testable embedded temperature library
#![cfg_attr(not(test), no_std)] use core::fmt; // Conditional imports for testing
#[cfg(test)]
use std::vec::Vec;
#[cfg(not(test))]
use heapless::Vec; /// Temperature reading optimized for embedded systems
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Temperature { // Store as i16 to save memory (16-bit vs 32-bit f32) // Resolution: 0.1°C, Range: -3276.8°C to +3276.7°C pub(crate) celsius_tenths: i16,
} impl Temperature { /// Create temperature from Celsius value pub const fn from_celsius(celsius: f32) -> Self { Self { celsius_tenths: (celsius * 10.0) as i16, } } /// Get temperature as Celsius f32 pub fn celsius(&self) -> f32 { self.celsius_tenths as f32 / 10.0 } pub fn fahrenheit(&self) -> f32 { self.celsius() * 9.0 / 5.0 + 32.0 } pub const fn is_overheating(&self) -> bool { self.celsius_tenths > 500 // > 50°C } pub const fn is_normal_range(&self) -> bool { self.celsius_tenths >= 150 && self.celsius_tenths <= 350 // 15-35°C }
} impl fmt::Display for Temperature { fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result { write!(f, "{:.1}°C", self.celsius()) }
} pub struct TemperatureBuffer<const N: usize> { #[cfg(test)] readings: Vec<Temperature>, // std::vec for tests #[cfg(not(test))] readings: Vec<Temperature, N>, // heapless::vec for embedded total_readings: u32,
} impl<const N: usize> TemperatureBuffer<N> { pub const fn new() -> Self { Self { readings: Vec::new(), total_readings: 0, } } pub fn push(&mut self, temperature: Temperature) { #[cfg(test)] { // In tests, we can grow unlimited if self.readings.len() >= N { self.readings.remove(0); } self.readings.push(temperature); } #[cfg(not(test))] { // In embedded, handle fixed capacity with circular buffer if self.readings.len() < N { self.readings.push(temperature).ok(); } else { // Use circular indexing (O(1) vs remove(0) which is O(n)) let oldest_index = (self.total_readings as usize) % N; self.readings[oldest_index] = temperature; } } self.total_readings += 1; } pub fn len(&self) -> usize { self.readings.len() } pub const fn capacity(&self) -> usize { N } pub fn latest(&self) -> Option<Temperature> { self.readings.last().copied() } pub fn average(&self) -> Option<Temperature> { if self.readings.is_empty() { return None; } let sum: i32 = self.readings.iter() .map(|t| t.celsius_tenths as i32) .sum(); let avg_tenths = sum / self.readings.len() as i32; Some(Temperature { celsius_tenths: avg_tenths as i16 }) } pub fn min(&self) -> Option<Temperature> { self.readings.iter() .min_by_key(|t| t.celsius_tenths) .copied() } pub fn max(&self) -> Option<Temperature> { self.readings.iter() .max_by_key(|t| t.celsius_tenths) .copied() } pub fn total_readings(&self) -> u32 { self.total_readings }
} #[cfg(test)]
mod tests { use super::*; #[test] fn test_temperature_creation_and_conversion() { let temp = Temperature::from_celsius(23.5); // Test precision assert!((temp.celsius() - 23.5).abs() < 0.1); // Test Fahrenheit conversion let fahrenheit = temp.fahrenheit(); assert!((fahrenheit - 74.3).abs() < 0.1); // Test memory efficiency assert_eq!(core::mem::size_of::<Temperature>(), 2); } #[test] fn test_temperature_ranges() { let normal = Temperature::from_celsius(25.0); assert!(normal.is_normal_range()); assert!(!normal.is_overheating()); let hot = Temperature::from_celsius(55.0); assert!(!hot.is_normal_range()); assert!(hot.is_overheating()); let cold = Temperature::from_celsius(5.0); assert!(!cold.is_normal_range()); assert!(!cold.is_overheating()); } #[test] fn test_temperature_edge_cases() { // Test extreme values let extreme_hot = Temperature::from_celsius(3276.0); let extreme_cold = Temperature::from_celsius(-3276.0); assert!(extreme_hot.celsius() > 3000.0); assert!(extreme_cold.celsius() < -3000.0); } #[test] fn test_buffer_basic_operations() { let mut buffer = TemperatureBuffer::<5>::new(); assert_eq!(buffer.len(), 0); assert_eq!(buffer.capacity(), 5); assert_eq!(buffer.latest(), None); // Add some readings buffer.push(Temperature::from_celsius(20.0)); buffer.push(Temperature::from_celsius(25.0)); buffer.push(Temperature::from_celsius(30.0)); assert_eq!(buffer.len(), 3); assert_eq!(buffer.total_readings(), 3); assert_eq!(buffer.latest().unwrap().celsius(), 30.0); } #[test] fn test_buffer_circular_behavior() { let mut buffer = TemperatureBuffer::<3>::new(); // Fill buffer exactly buffer.push(Temperature::from_celsius(10.0)); buffer.push(Temperature::from_celsius(20.0)); buffer.push(Temperature::from_celsius(30.0)); assert_eq!(buffer.len(), 3); // Add one more - should overwrite oldest buffer.push(Temperature::from_celsius(40.0)); assert_eq!(buffer.len(), 3); // Still full assert_eq!(buffer.total_readings(), 4); // But total increased // First reading (10.0) should be gone assert_eq!(buffer.min().unwrap().celsius(), 20.0); // Min is now 20 assert_eq!(buffer.max().unwrap().celsius(), 40.0); // Max is 40 } #[test] fn test_buffer_statistics() { let mut buffer = TemperatureBuffer::<10>::new(); // Add test data: 20, 21, 22, 23, 24 for i in 0..5 { buffer.push(Temperature::from_celsius(20.0 + i as f32)); } let avg = buffer.average().unwrap(); assert!((avg.celsius() - 22.0).abs() < 0.1); assert_eq!(buffer.min().unwrap().celsius(), 20.0); assert_eq!(buffer.max().unwrap().celsius(), 24.0); } #[test] fn test_buffer_empty_statistics() { let buffer = TemperatureBuffer::<5>::new(); assert_eq!(buffer.average(), None); assert_eq!(buffer.min(), None); assert_eq!(buffer.max(), None); } #[test] fn test_buffer_single_reading() { let mut buffer = TemperatureBuffer::<5>::new(); buffer.push(Temperature::from_celsius(25.0)); let avg = buffer.average().unwrap(); assert_eq!(avg.celsius(), 25.0); assert_eq!(buffer.min().unwrap().celsius(), 25.0); assert_eq!(buffer.max().unwrap().celsius(), 25.0); } #[test] fn test_temperature_display() { let temp = Temperature::from_celsius(23.7); let display_str = format!("{}", temp); assert_eq!(display_str, "23.7°C"); } #[test] fn test_memory_usage() { // Verify our types are memory efficient let temp_size = core::mem::size_of::<Temperature>(); let buffer_size = core::mem::size_of::<TemperatureBuffer<20>>(); println!("Temperature size: {} bytes", temp_size); println!("Buffer size (20 readings): {} bytes", buffer_size); assert_eq!(temp_size, 2); // Should be exactly 2 bytes // Buffer size will be larger in tests due to std::Vec }
}

