#[cfg(test)]
pub struct MockTemperatureSensor { temperatures: RefCell<Vec<f32>>, current_index: RefCell<usize>, id: String,
} #[cfg(test)]
impl MockTemperatureSensor { pub fn new(id: String) -> Self { Self { temperatures: RefCell::new(vec![25.0]), // Default temperature current_index: RefCell::new(0), id, } } pub fn set_temperatures(&self, temps: Vec<f32>) { *self.temperatures.borrow_mut() = temps; *self.current_index.borrow_mut() = 0; } pub fn set_single_temperature(&self, temp: f32) { *self.temperatures.borrow_mut() = vec![temp]; *self.current_index.borrow_mut() = 0; }
