use proc_macro::TokenStream;
use quote::quote;
use syn::{parse_macro_input, DeriveInput}; #[proc_macro_derive(MyDebug)]
pub fn my_debug_derive(input: TokenStream) -> TokenStream { let input = parse_macro_input!(input as DeriveInput); let name = &input.ident; let expanded = quote! { impl std::fmt::Debug for #name { fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result { write!(f, "{}(custom debug)", stringify!(#name)) } } }; TokenStream::from(expanded)
} // Usage:
#[derive(MyDebug)]
struct Person { name: String, age: u32,
} let p = Person { name: "Alice".into(), age: 30 };
println!("{:?}", p); // Person(custom debug) Derive with Helper Attributes // Derive macro with custom attributes
#[proc_macro_derive(Builder, attributes(builder))]
pub fn derive_builder(input: TokenStream) -> TokenStream { let input = parse_macro_input!(input as DeriveInput); let name = &input.ident; let builder_name = syn::Ident::new( &format!("{}Builder", name), name.span() ); // Extract fields from struct let fields = match &input.data { syn::Data::Struct(data) => &data.fields, _ => panic!("Builder can only be derived for structs"), }; // Generate builder implementation let builder_fields: Vec<_> = fields.iter().map(|f| { let name = &f.ident; let ty = &f.ty; quote! { #name: Option<#ty> } }).collect(); let builder_methods = fields.iter().map(|f| { let name = &f.ident; let ty = &f.ty; quote! { pub fn #name(mut self, value: #ty) -> Self { self.#name = Some(value); self } } }); let build_fields = fields.iter().map(|f| { let name = &f.ident; quote! { #name: self.#name.expect(concat!(stringify!(#name), " is required")) } }); // Create initial values for builder let builder_init: Vec<_> = fields.iter().map(|f| { let name = &f.ident; quote! { #name: None } }).collect(); let expanded = quote! { pub struct #builder_name { #(#builder_fields,)* } impl #builder_name { #(#builder_methods)* pub fn build(self) -> #name { #name { #(#build_fields,)* } } } impl #name { pub fn builder() -> #builder_name { #builder_name { #(#builder_init,)* } } } }; TokenStream::from(expanded)
} // Usage:
#[derive(Builder)]
struct Config { host: String, port: u16, #[builder(default = "false")] debug: bool,
} let config = Config::builder() .host("localhost".into()) .port(8080) .build();

