Rust offers three loop constructs, each with specific use cases: loop - Infinite Loop with Break // Infinite loop - must break explicitly
let mut counter = 0;
let result = loop { counter += 1; if counter == 10 { break counter * 2; // loop can return a value! }
};
println!("Result: {}", result); // Prints: Result: 20 // Loop labels for nested loops
'outer: loop { println!("Entered outer loop"); 'inner: loop { println!("Entered inner loop"); break 'outer; // Break the outer loop } println!("This won't execute");
} while - Conditional Loop // Standard while loop
let mut number = 3;
while number != 0 { println!("{}!", number); number -= 1;
}
println!("LIFTOFF!!!"); // Common pattern: checking conditions
let mut stack = vec![1, 2, 3];
while !stack.is_empty() { let value = stack.pop(); println!("Popped: {:?}", value);
} for - Iterator Loop The for loop is the most idiomatic way to iterate in Rust: // Iterate over a collection
let numbers = vec![1, 2, 3, 4, 5];
for num in &numbers { println!("{}", num);
} // Range syntax (exclusive end)
for i in 0..5 { println!("{}", i); // Prints 0, 1, 2, 3, 4
} // Inclusive range
for i in 1..=5 { println!("{}", i); // Prints 1, 2, 3, 4, 5
} // Enumerate for index and value
let items = vec!["a", "b", "c"];
for (index, value) in items.iter().enumerate() { println!("{}: {}", index, value);
} // Reverse iteration
for i in (1..=3).rev() { println!("{}", i); // Prints 3, 2, 1
