} /// Process data with the Rust implementation
#[no_mangle]
pub extern "C" fn rust_processor_process( processor: *mut RustProcessor, input: *const c_char, output: *mut c_char, output_len: usize,
) -> i32 { if processor.is_null() || input.is_null() || output.is_null() { return -1; } unsafe { let processor = &mut *(processor as *mut ProcessorImpl); let input_str = match CStr::from_ptr(input).to_str() { Ok(s) => s, Err(_) => return -2, }; let result = processor.process(input_str); let result_bytes = result.as_bytes(); if result_bytes.len() >= output_len { return -3; } std::ptr::copy_nonoverlapping( result_bytes.as_ptr(), output as *mut u8, result_bytes.len(), ); *output.add(result_bytes.len()) = 0; result_bytes.len() as i32 }
} /// Free the processor instance
#[no_mangle]
pub extern "C" fn rust_processor_free(processor: *mut RustProcessor) { if !processor.is_null() { unsafe { let _ = Box::from_raw(processor as *mut ProcessorImpl); } }
} // Internal implementation
