When you write to a memory location in regular code, the compiler assumes it has complete control over that memory. It can optimize away "redundant" reads and writes: // Regular memory access - compiler can optimize
fn regular_memory() { let mut value = 0u32; value = 1; // Compiler might optimize away value = 2; // Only this write matters value = 3; // And this one let x = value; // Reads 3 let y = value; // Compiler might reuse x instead of reading again
} But hardware registers are different. They're not regular memory - they're windows into hardware state: // Hardware register at address 0x4000_0000
const GPIO_OUT: *mut u32 = 0x4000_0000 as *mut u32; unsafe fn bad_gpio_control() { // ❌ WRONG: Compiler might optimize these away! *GPIO_OUT = 0b0001; // Turn on LED 1 *GPIO_OUT = 0b0010; // Turn on LED 2 *GPIO_OUT = 0b0100; // Turn on LED 3 // Compiler might only emit the last write!
} unsafe fn good_gpio_control() { use core::ptr; // ✅ CORRECT: Volatile writes are never optimized away ptr::write_volatile(GPIO_OUT, 0b0001); // Turn on LED 1 ptr::write_volatile(GPIO_OUT, 0b0010); // Turn on LED 2 ptr::write_volatile(GPIO_OUT, 0b0100); // Turn on LED 3 // All three writes will happen!
}

