use core::ptr; /// Safe wrapper for a hardware register
pub struct Register<T> { addr: *mut T,
} impl<T> Register<T> { /// Create a new register at the given address pub const fn new(addr: usize) -> Self { Self { addr: addr as *mut T, } } /// Read the current value (volatile) pub unsafe fn read(&self) -> T where T: Copy, { ptr::read_volatile(self.addr) } /// Write a new value (volatile) pub unsafe fn write(&self, value: T) { ptr::write_volatile(self.addr, value); } /// Modify the register with read-modify-write pub unsafe fn modify<F>(&self, f: F) where T: Copy, F: FnOnce(T) -> T, { let value = self.read(); self.write(f(value)); }
} // Usage example
const PORTA_OUT: Register<u32> = Register::new(0x4000_0000); unsafe fn toggle_pin(pin: u8) { PORTA_OUT.modify(|v| v ^ (1 << pin));
}

