Most hardware registers pack multiple fields into single words: /// GPIO Configuration Register Layout (ESP32-C3 example)
/// Bits 0-1: Drive strength
/// Bits 2-3: Pin function
/// Bit 4: Pull-up enable
/// Bit 5: Pull-down enable
/// Bit 6: Input enable
/// Bit 7: Output enable pub struct GpioConfig { reg: ReadWrite<u32>,
} impl GpioConfig { const DRIVE_MASK: u32 = 0b11; const DRIVE_SHIFT: u32 = 0; const FUNC_MASK: u32 = 0b11; const FUNC_SHIFT: u32 = 2; const PULLUP_BIT: u32 = 4; const PULLDOWN_BIT: u32 = 5; const INPUT_BIT: u32 = 6; const OUTPUT_BIT: u32 = 7; pub unsafe fn set_drive_strength(&self, strength: u8) { self.reg.modify(|v| { (v & !(Self::DRIVE_MASK << Self::DRIVE_SHIFT)) | ((strength as u32 & Self::DRIVE_MASK) << Self::DRIVE_SHIFT) }); } pub unsafe fn enable_pullup(&self, enable: bool) { self.reg.modify(|v| { if enable { v | (1 << Self::PULLUP_BIT) } else { v & !(1 << Self::PULLUP_BIT) } }); } pub unsafe fn set_as_output(&self) { self.reg.modify(|v| { v | (1 << Self::OUTPUT_BIT) | (1 << Self::INPUT_BIT) }); }
