/// ESP32-C3 Interrupt Controller
const INTERRUPT_BASE: usize = 0x600C_2000; pub struct InterruptController { /// Interrupt enable register enable: ReadWrite<u32>, /// Interrupt pending register (read-only) pending: ReadOnly<u32>, /// Interrupt clear register (write-only) clear: WriteOnly<u32>,
} impl InterruptController { pub const fn new() -> Self { Self { enable: ReadWrite::new(INTERRUPT_BASE + 0x00), pending: ReadOnly::new(INTERRUPT_BASE + 0x04), clear: WriteOnly::new(INTERRUPT_BASE + 0x08), } } /// Enable an interrupt pub unsafe fn enable_interrupt(&self, irq: u8) { self.enable.modify(|v| v | (1 << irq)); } /// Check if interrupt is pending pub unsafe fn is_pending(&self, irq: u8) -> bool { (self.pending.read() >> irq) & 1 == 1 } /// Clear a pending interrupt pub unsafe fn clear_interrupt(&self, irq: u8) { self.clear.write(1 << irq); } /// Handle all pending interrupts pub unsafe fn handle_pending(&self) { let pending = self.pending.read(); // Process each pending interrupt for irq in 0..32 { if (pending >> irq) & 1 == 1 { // Handle interrupt self.handle_irq(irq); // Clear it self.clear.write(1 << irq); } } } fn handle_irq(&self, irq: u8) { // Dispatch to appropriate handler match irq { 0 => handle_timer_interrupt(), 1 => handle_uart_interrupt(), 2 => handle_gpio_interrupt(), _ => handle_unknown_interrupt(irq), } }
}

