/// Hardware timer with microsecond precision
pub struct Timer { /// Timer counter register (64-bit, read-only) counter_lo: ReadOnly<u32>, counter_hi: ReadOnly<u32>, /// Timer reload value (write-only) reload: WriteOnly<u32>, /// Timer control register control: ReadWrite<u32>,
} impl Timer { const BASE: usize = 0x6002_0000; pub const fn new() -> Self { Self { counter_lo: ReadOnly::new(Self::BASE + 0x00), counter_hi: ReadOnly::new(Self::BASE + 0x04), reload: WriteOnly::new(Self::BASE + 0x08), control: ReadWrite::new(Self::BASE + 0x0C), } } /// Read 64-bit counter atomically pub unsafe fn read_counter(&self) -> u64 { // Must read in correct order to handle rollover loop { let hi1 = self.counter_hi.read(); let lo = self.counter_lo.read(); let hi2 = self.counter_hi.read(); // If high didn't change, we got a consistent read if hi1 == hi2 { return ((hi1 as u64) << 32) | (lo as u64); } // Otherwise retry (rollover happened during read) } } /// Set timer period in microseconds pub unsafe fn set_period_us(&self, us: u32) { // Assuming 160MHz clock const TICKS_PER_US: u32 = 160; self.reload.write(us * TICKS_PER_US); } /// Enable timer with interrupt pub unsafe fn enable_with_interrupt(&self) { self.control.modify(|v| { v | (1 << 0) // Enable bit | (1 << 1) // Auto-reload bit | (1 << 2) // Interrupt enable bit }); }
}

